import{c as r,Q as o,j as n,m as a}from"./chunks/framework.rWdQudnF.js";const u=JSON.parse('{"title":"中间件技术","description":"","frontmatter":{"title":"中间件技术"},"headers":[],"relativePath":"综合知识/架构设计/中间件技术.md","filePath":"综合知识/架构设计/中间件技术.md","lastUpdated":null}'),s={name:"综合知识/架构设计/中间件技术.md"};function d(e,t,l,i,g,h){return o(),n("div",null,[...t[0]||(t[0]=[a('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 构件定义、特性与分类</li><li>[x] 构件组装技术</li><li>[x] EJB 构件模型（会话型/实体型/消息驱动）</li><li>[x] CORBA（伺服对象/POA/ORB/IDL）</li><li>[x] COM 对象重用（包含 vs 聚集）</li><li>[x] 中间件功能（连接通信/事务管理/负载均衡）</li><li>[x] ESB（企业服务总线）与 SOA</li><li>[x] SDN 架构</li><li>[x] 接口标准化</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h2 id="构件" tabindex="-1">构件 <a class="header-anchor" href="#构件" aria-label="Permalink to &quot;构件&quot;">​</a></h2><h3 id="构件基础" tabindex="-1">构件基础 <a class="header-anchor" href="#构件基础" aria-label="Permalink to &quot;构件基础&quot;">​</a></h3><blockquote><p><strong>软件构件</strong>是独立可部署的软件单元，与对象不同，构件可以利用容器管理自身对外的可见状态。</p></blockquote><p><strong>构件核心特性：</strong></p><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td><strong>独立部署单元</strong></td><td>可单独编译、部署和替换</td></tr><tr><td><strong>第三方组装单元</strong></td><td>支持通过接口被其他系统复用</td></tr><tr><td><strong>无外部可见状态</strong></td><td>通过接口交互，内部状态对外透明</td></tr><tr><td><strong>不可拆分</strong></td><td>作为部署单元是原子单位</td></tr><tr><td><strong>容器管理</strong></td><td>由容器管理生命周期和状态</td></tr></tbody></table><p><strong>构件 vs 对象的区别：</strong></p><ul><li>构件依赖容器管理（对象自主管理）</li><li>构件强调部署单元（对象强调实例）</li><li>构件通过接口交互（对象可直接调用）</li><li>构件不共享类元素（强调独立性）</li><li>构件实例由容器创建而非自身构造</li></ul><p><strong>构件五类（按外部形态）：</strong></p><ol><li><strong>独立而成熟的构件</strong> — 已在实际环境多次检验</li><li><strong>有限制的构件</strong> — 提供接口，指出使用条件和前提</li><li><strong>适应性构件</strong> — 进行了包装或接口技术处理，可直接使用</li><li><strong>装配的构件</strong> — 已装配在不同层次上，可连续使用</li><li><strong>可修改的构件</strong> — 可进行版本替换，通过重新&quot;包装&quot;或写接口实现替换</li></ol><hr><h3 id="构件分类与组装" tabindex="-1">构件分类与组装 <a class="header-anchor" href="#构件分类与组装" aria-label="Permalink to &quot;构件分类与组装&quot;">​</a></h3><p><strong>构件分类三大方法：</strong></p><table tabindex="0"><thead><tr><th>方法</th><th>特点</th></tr></thead><tbody><tr><td><strong>关键字分类法</strong></td><td>按抽象到具体顺序逐次分解为树形或有向无回路图结构</td></tr><tr><td><strong>刻面分类法</strong></td><td>利用 Facet 描述构件执行的功能、被操作的数据、应用语境等特征</td></tr><tr><td><strong>超文本方法</strong></td><td>按人类联想思维方式任意跳转到相关概念或构件的文档</td></tr></tbody></table><p><strong>构件组装技术：</strong></p><ul><li>基于功能的构件组装技术</li><li>基于数据的构件组装技术</li><li>面向对象的构件组装技术</li><li>⚠️ &quot;基于实现的构件组装技术&quot; <strong>不是</strong>标准分类</li></ul><p><strong>构件组装三层次：</strong> 集成（Integration）→ 扩展（Extension）→ 演化（Evolution）</p><hr><h3 id="ejb-构件模型" tabindex="-1">EJB 构件模型 <a class="header-anchor" href="#ejb-构件模型" aria-label="Permalink to &quot;EJB 构件模型&quot;">​</a></h3><blockquote><p>J2EE 支持五种标准构件模型：<strong>Applet、Servlet、JSP、EJB、Application Client</strong></p></blockquote><p><strong>EJB 三种构件类型：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>职责</th><th>特点</th></tr></thead><tbody><tr><td><strong>会话型构件</strong>（Session Bean）</td><td>负责完成<strong>服务端与客户端交互</strong>，处理业务逻辑</td><td>处理业务规则、工作流</td></tr><tr><td><strong>实体型构件</strong>（Entity Bean）</td><td>用于<strong>数据持久化</strong>，简化数据库开发</td><td>每个实例对应数据库记录（已被 JPA 替代）</td></tr><tr><td><strong>消息驱动构件</strong>（Message-Driven Bean）</td><td>处理<strong>并发和异步访问</strong>操作</td><td>基于 JMS，解耦系统组件</td></tr></tbody></table><hr><h3 id="corba" tabindex="-1">CORBA <a class="header-anchor" href="#corba" aria-label="Permalink to &quot;CORBA&quot;">​</a></h3><p>商用构件标准规范 - CORBA（公共对象请求代理体系结构）</p><p><strong>CORBA（Common Object Request Broker Architecture，公共对象请求代理体系结构）</strong> 是由 <strong>OMG（对象管理组织）</strong> 制定的<strong>面向对象分布式中间件规范</strong>，也是早期最重要的<strong>商用构件标准规范</strong>之一。</p><p><strong>核心组件：</strong></p><table tabindex="0"><thead><tr><th>组件</th><th>职责</th></tr></thead><tbody><tr><td><strong>伺服对象</strong>（Servant）</td><td>CORBA 对象的<strong>真正实现</strong>，负责完成客户端请求</td></tr><tr><td><strong>对象适配器</strong>（POA）</td><td>管理伺服对象生命周期，但不实现业务逻辑</td></tr><tr><td><strong>对象请求代理</strong>（ORB）</td><td>负责通信路由，不涉及业务实现</td></tr><tr><td><strong>适配器激活器</strong></td><td>辅助 POA 的扩展组件</td></tr></tbody></table><p><strong>IDL（接口定义语言）：</strong></p><ul><li>IDL 文件包含六种元素：模块、接口、类型、常量、异常、值类型</li><li><strong>接口描述</strong>是 IDL 文件最核心的内容</li><li><strong>模块定义</strong>映射为 Java 的 Package 或 C++ 的 Namespace</li></ul><hr><p>对象管理组织(OMG) 基于CORBA基础设施定义了<strong>四种构件标准</strong>。</p><ul><li>实体(Entity)构件需要长期持久化并主要用于事务性行为，由容器管理其持久化。</li><li>加工(Process)构件同样需要容器管理其持久化，但没有客户端可访问的主键。</li><li>会话(Session)构件不需要容器管理其持久化，其状态信息必须由构件自己管理。</li><li>服务(Service)构件是无状态的。</li></ul><hr><h3 id="com-对象重用" tabindex="-1">COM 对象重用 <a class="header-anchor" href="#com-对象重用" aria-label="Permalink to &quot;COM 对象重用&quot;">​</a></h3><p>COM 支持两种对象组装形式：</p><table tabindex="0"><thead><tr><th>形式</th><th>机制</th><th>特点</th><th>类比设计模式</th></tr></thead><tbody><tr><td><strong>包含</strong>（Containment）</td><td>外部对象拥有内部对象的唯一引用，<strong>转发请求</strong></td><td>外部完全封装内部</td><td>装饰器模式</td></tr><tr><td><strong>聚集</strong>（Aggregation）</td><td>直接把内部对象的接口引用传给外部对象的客户，<strong>不再转发</strong></td><td>内部对象可独立使用，效率更高</td><td>组合模式</td></tr></tbody></table><hr><h2 id="中间件和其他" tabindex="-1">中间件和其他 <a class="header-anchor" href="#中间件和其他" aria-label="Permalink to &quot;中间件和其他&quot;">​</a></h2><h3 id="中间件" tabindex="-1">中间件 <a class="header-anchor" href="#中间件" aria-label="Permalink to &quot;中间件&quot;">​</a></h3><blockquote><p>中间件是提供平台和应用之间的通用服务，具有标准的程序接口和协议。</p></blockquote><p><strong>三大核心功能：</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th><th>典型技术</th></tr></thead><tbody><tr><td><strong>连接和通信</strong></td><td>为客户端和服务器提供连接通道，实现协议转换，管理连接生命周期</td><td>MQ、RPC 框架</td></tr><tr><td><strong>交易管理机制</strong></td><td>保证交易一致性，采用 2PC 等机制</td><td>事务管理器（Tuxedo）</td></tr><tr><td><strong>负载均衡和高可用性</strong></td><td>故障转移、服务降级熔断</td><td>Nginx、Keepalived、Hystrix</td></tr></tbody></table><p><strong>两种中间件类型对比：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>特点</th></tr></thead><tbody><tr><td><strong>消息中间件</strong></td><td>采用异步处理模式、松耦合关系；消息传递模型：<strong>点对点模型</strong>和<strong>发布-订阅模型</strong></td></tr><tr><td><strong>分布式对象中间件</strong></td><td>由一组对象提供系统服务，对象间能跨平台通信</td></tr></tbody></table><hr><h3 id="esb-与-soa" tabindex="-1">ESB 与 SOA <a class="header-anchor" href="#esb-与-soa" aria-label="Permalink to &quot;ESB 与 SOA&quot;">​</a></h3><blockquote><p>**ESB（企业服务总线）**是由中间件技术实现并支持 SOA 的一组基础架构。</p></blockquote><p><strong>ESB 核心优势：</strong></p><ul><li><strong>消除了服务请求者与服务提供者之间的直接链接</strong></li><li>通过总线架构实现松耦合</li><li>服务双方只需与总线交互，不需知道对方位置</li></ul><blockquote><p>微服务架构采用<strong>去中心化</strong>管理，SOA 采用<strong>集中式</strong>管理（依赖 ESB 进行服务协调）。</p></blockquote><hr><h3 id="sdn-软件定义网络" tabindex="-1">SDN（软件定义网络） <a class="header-anchor" href="#sdn-软件定义网络" aria-label="Permalink to &quot;SDN（软件定义网络）&quot;">​</a></h3><p>SDN 标准架构分为三层：</p><ol><li><strong>应用层</strong> — 承载各类网络应用，通过北向接口与控制层交互</li><li><strong>控制层</strong> — 集中化的控制器，通过南向接口管理转发层设备</li><li><strong>转发层</strong> — 数据平面设备，负责实际数据包转发</li></ol><blockquote><p>⚠️ &quot;逻辑层&quot;<strong>不是</strong> SDN 标准架构中的定义层级。</p></blockquote><hr><h3 id="接口标准化" tabindex="-1">接口标准化 <a class="header-anchor" href="#接口标准化" aria-label="Permalink to &quot;接口标准化&quot;">​</a></h3><blockquote><p>接口标准化是对<strong>接口中消息模式、格式和协议</strong>的标准化。</p></blockquote><p><strong>需要使接口得到广泛应用，必须实现接口标准化，核心是：</strong></p><ul><li>消息模式（Message Patterns）— 定义交互的基本模式</li><li>消息格式（Message Formats）— 规定数据的组织方式</li><li>通信协议（Protocols）— 确定传输规则和时序</li></ul>',63)])])}const p=r(s,[["render",d]]);export{u as __pageData,p as default};
